async function runtimeRequest(method, endpoint, body, timeoutMs = 30_000) {
  const base = (() => { const base = String($env.MERCHROUTE_RUNTIME_BASE_URL || '').trim().replace(/\/+$/, ''); if (!base) throw new Error('MERCHROUTE_RUNTIME_BASE_URL 未配置，禁止发出 MerchRoute runtime 请求'); return base; })();
  const key = String($env.MERCHROUTE_RUNTIME_KEY || '').trim();
  if (!key) throw new Error('MERCHROUTE_RUNTIME_KEY 未配置，无法访问 MerchRoute WB runtime API');
  const RuntimeURL = require('url').URL;
  const target = new RuntimeURL(base + endpoint);
  const payload = body === undefined ? '' : JSON.stringify(body);
  const transport = target.protocol === 'https:' ? require('https') : require('http');
  const response = await new Promise((resolve, reject) => {
    const request = transport.request(target, {
      method,
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'X-MerchRoute-Runtime-Key': key,
        ...(payload ? { 'Content-Length': Buffer.byteLength(payload) } : {}),
      },
    }, (incoming) => {
      const chunks = [];
      let bytes = 0;
      incoming.on('data', (chunk) => {
        bytes += chunk.length;
        if (bytes > 20 * 1024 * 1024) {
          request.destroy(new Error('MerchRoute runtime API 响应超过 20 MiB 限制'));
          return;
        }
        chunks.push(chunk);
      });
      incoming.on('end', () => resolve({
        status: Number(incoming.statusCode || 0),
        text: Buffer.concat(chunks).toString('utf8'),
      }));
    });
    const boundedTimeoutMs = Math.max(1_000, Math.min(180_000, Number(timeoutMs) || 30_000));
    request.setTimeout(boundedTimeoutMs, () => request.destroy(new Error('MerchRoute runtime API 请求超时')));
    request.on('error', reject);
    if (payload) request.write(payload);
    request.end();
  });
  const text = response.text;
  let data = {};
  if (text) {
    try { data = JSON.parse(text); } catch (_) { data = { raw: text }; }
  }
  if (response.status < 200 || response.status >= 300) {
    const nestedError = data && typeof data.error === 'object' && data.error !== null ? data.error : {};
    const errorValue = typeof data.error === 'string' ? data.error : '';
    const error = new Error(String(data.message || nestedError.message || errorValue || data.code || nestedError.code || ('MerchRoute runtime API HTTP ' + response.status)));
    error.code = String(data.code || nestedError.code || errorValue || 'RUNTIME_API_FAILED');
    error.httpStatus = response.status;
    error.details = data;
    throw error;
  }
  return data;
}
