  result: runtime.finalResult || undefined,
} }];

const source = $input.first().json || {};
const raw = source.error && typeof source.error === 'object' ? source.error : source;
const details = raw.details && typeof raw.details === 'object' ? raw.details : {};
const nested = details.error && typeof details.error === 'object' ? details.error : {};
const taskId = String($('Validate GET Query').first().json.taskId || '');
const httpStatus = Number(raw.httpStatus || details.httpStatus || details.statusCode || nested.httpStatus || nested.statusCode || 0);
const code = String(raw.code || details.code || nested.code || '').toUpperCase();
const runtimeMessage = String(raw.message || source.message || source.description || nested.message || '').slice(0, 500);
if (httpStatus === 404 || code === 'NOT_FOUND') {
  return [{ json: {
    httpStatus: 404,
    error: 'not_found',
    message: '任务不存在',
    taskId,
  } }];
}
return [{ json: {
  httpStatus: 500,
  error: 'runtime_api_failed',
  message: '任务查询失败，请查看 n8n 执行记录',
